// Swagger / OpenAPI 3.0 configuration
const path = require('path');
const swaggerJSDoc = require('swagger-jsdoc');
const swaggerUi = require('swagger-ui-express');

const options = {
  definition: {
    openapi: '3.0.0',
    info: {
      title: 'RESTful API Documentation - Web & Database Lab 3',
      version: '1.0.0',
      description:
        'Interactive API documentation auto-generated by Swagger UI for the Sales Management application'
    },
    servers: [
      {
        url: 'http://localhost:3000/api',
        description: 'Development Local Server'
      }
    ],
    // Reusable pieces shared by every endpoint (referenced with $ref)
    components: {
      parameters: {
        id: {
          in: 'path',
          name: 'id',
          required: true,
          schema: { type: 'string', example: '6aa7c8310cb5dc7bff6e7b19' },
          description: 'MongoDB ObjectId of the resource'
        }
      },
      schemas: {
        Error: {
          type: 'object',
          properties: {
            success: { type: 'boolean', example: false },
            error: { type: 'string', example: 'Something went wrong' }
          }
        }
      }
    }
  },
  // Absolute paths, so it works no matter which folder you run "node server.js" from
 apis: [
  path.join(__dirname, '../routes/*.js').replace(/\\/g, '/'),
  path.join(__dirname, '../models/*.js').replace(/\\/g, '/')
]
};

const swaggerSpec = swaggerJSDoc(options);

const setupSwagger = (app) => {
  app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerSpec));
  console.log('Swagger UI documentation is ready at: http://localhost:3000/api-docs');
};

module.exports = setupSwagger;
